package com.tallerexpress.model;
import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.ArrayList; import java.util.List;
public class ServiceOrder {
    private int id,clientId,vehicleId; private String mechanicName,problemDescription,diagnosis; private LocalDateTime entryDate; private OrderStatus status; private BigDecimal finalCost=BigDecimal.ZERO; private List<OrderPart> parts=new ArrayList<>();
    public int getId(){return id;} public void setId(int v){id=v;} public int getClientId(){return clientId;} public void setClientId(int v){clientId=v;} public int getVehicleId(){return vehicleId;} public void setVehicleId(int v){vehicleId=v;} public String getMechanicName(){return mechanicName;} public void setMechanicName(String v){mechanicName=v;} public String getProblemDescription(){return problemDescription;} public void setProblemDescription(String v){problemDescription=v;} public String getDiagnosis(){return diagnosis;} public void setDiagnosis(String v){diagnosis=v;} public LocalDateTime getEntryDate(){return entryDate;} public void setEntryDate(LocalDateTime v){entryDate=v;} public OrderStatus getStatus(){return status;} public void setStatus(OrderStatus v){status=v;} public BigDecimal getFinalCost(){return finalCost;} public void setFinalCost(BigDecimal v){finalCost=v;} public List<OrderPart> getParts(){return parts;} public void setParts(List<OrderPart> v){parts=v;}
}
